#!/usr/bin/env python3
"""Expand SOC FIELDWORK with a curated defensive operations practice pack.

Each row is a standalone technical teaching unit: a behavioral mechanism,
observable evidence, a caveat, and an investigation next step. No live attacks.
"""
import json
import re
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
d=json.loads((ROOT/'content.json').read_text(encoding='utf-8'))

# Safe to rerun: do not append the same learning pack twice.
if any(x.get('title') == 'Reading a five-tuple' for x in d['lessons']):
    print('Edition 04 content already installed; nothing to append.')
    raise SystemExit(0)

